//! Complete immutable-original Loot comparisons; finite pages carry no EOF receipt.
use crate::lint::Registry;
#[path="../fixtures/original_policies/sys_loot.rs"]mod original;
#[path="../fixtures/native-sys-loot/fixture.rs"]mod fixture;
fn record(outcome:&crate::run::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
#[test]fn unique_sys_loot_preserves_full_original_cross_file_roots_exemptions_allow_rule_order_and_report(){for case in fixture::CASES{let root=crate::test_scratch::dir(&format!("sys-loot-original-{case}"));for(relative,bytes)in fixture::files(case).unwrap(){let file=root.join(relative);std::fs::create_dir_all(file.parent().unwrap()).unwrap();std::fs::write(file,bytes).unwrap();}let options=crate::run::Options{root:root.clone(),lints:vec!["sys/loot".into()],raw:true,no_cache:true,..Default::default()};let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,options.clone()).unwrap();let current=crate::run::Engine::new(crate::run::registry(),options).unwrap();let expected=old.run_one(old.reg.lints[0].as_ref());let actual=current.run_one(current.reg.lints.iter().find(|lint|lint.meta().name=="sys/loot").unwrap().as_ref());assert_eq!(record(&actual),record(&expected),"entire original Loot report {case}");assert!(!expected.run.sites.is_empty());if *case=="allowed"{assert!(expected.allow_used.iter().any(|u|u.code=="RETAINED"));}println!("SYS_LOOT_WHOLE_ORIGINAL={}",serde_json::json!({"case":case,"record":record(&actual)}));}}
#[cfg(feature="native-policy")]
struct Pages<'a>{root:&'a std::path::Path,rows:Vec<(String,dm_preprocess::SourceText)>,budget:std::sync::Arc<crate::captured_generator_budget::Budget>,config:crate::captured_raw_file::Config,passes:std::cell::Cell<usize>,stop:Option<usize>}
#[cfg(feature="native-policy")]
impl crate::reactive_raw_policy_pages::RawPolicyPages for Pages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,crate::captured_raw_file::RawPolicyViews<'_>)->Result<bool,crate::captured_reactive_reads::Failure>)->Result<bool,crate::captured_reactive_reads::Failure>{let pass=self.passes.get();self.passes.set(pass+1);for(relative,text)in &self.rows{if self.config.policy_path_exempt("sys/loot","sys",relative){continue}if !crate::captured_raw_file::with_original_policy_file(self.root,&self.root.join(relative),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(self.stop!=Some(pass))}}
#[cfg(feature="native-policy")]
#[test]fn native_sys_loot_data_matches_frozen_original_sites_allow_and_entire_source_lines_without_completion_authority(){use crate::{captured_generator_budget::Budget,captured_raw_policy::Configuration};for case in fixture::CASES{let root=crate::test_scratch::dir(&format!("sys-loot-native-data-{case}"));let files=fixture::files(case).unwrap();for(relative,text)in &files{let file=root.join(relative);std::fs::create_dir_all(file.parent().unwrap()).unwrap();std::fs::write(file,text).unwrap();}let options=crate::run::Options{root:root.clone(),lints:vec!["sys/loot".into()],raw:true,no_cache:true,..Default::default()};let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,options).unwrap();let expected=old.run_one(old.reg.lints[0].as_ref());let budget=Budget::new(32*1024*1024).unwrap();let mut rows=Vec::new();for(relative,text)in &files{if !crate::dm::sys::policy_selection().matches_path(relative){continue}let acquired=dm_preprocess::AcquiredSource::from_original_bytes(text.clone(),());rows.push((relative.clone(),acquired.lease().source_text().clone()));}rows.sort_by(|a,b|a.0.cmp(&b.0));let config=files.iter().find(|(relative,_)|relative=="tools/ci/lint_scopes.toml").unwrap().1.as_slice();let mut pages=Pages{root:&root,rows,budget:budget.clone(),config:crate::captured_raw_file::Config::capture(Configuration::Captured(config)).unwrap(),passes:std::cell::Cell::new(0),stop:None};let actual=crate::captured_sys_loot_pages::collect(&pages,&pages.config,&budget,&||Ok(())).unwrap();assert_eq!(actual.sites(),expected.run.sites.as_slice());assert_eq!(actual.allow_used(),expected.allow_used.as_slice());assert_eq!(pages.passes.get(),2);for(site,text)in actual.sites().iter().zip(actual.source_text()){assert_eq!(*text,old.tree.site_text(&site.rel,site.line as usize));}for used in actual.allow_used(){assert_eq!(actual.allow_source_digest(&used.rel),Some(&crate::captured_raw_file::source_allow_digest(old.tree.get(&used.rel).unwrap())));}
 pages.passes.set(0);pages.stop=Some(1);let fresh=Budget::new(32*1024*1024).unwrap();assert!(crate::captured_sys_loot_pages::collect(&pages,&pages.config,&fresh,&||Ok(())).is_err());let fresh=Budget::new(32*1024*1024).unwrap();assert!(matches!(crate::captured_sys_loot_pages::collect(&pages,&pages.config,&fresh,&||Err(std::io::Error::from_raw_os_error(1450))),Err(crate::reactive_reads_native::Failure::Operational(ref e))if e.raw_os_error()==Some(1450)));}}
